func bridgeTone(state string) string {
	switch state {
	case "ok":
		return "ok"
	case "unreachable":
		return "warn"
	}
	return "bad"
}

func bridgeStateLabel(state string) string {
	switch state {
	case "ok":
		return "Connected"
	case "unreachable":
		return "Cannot be reached"
	}
	return "Key revoked"
}

