func destKindLabel(ctx context.Context, kind string) string {
	switch kind {
	case "folder":
		return t(ctx, "folder")
	case "webdav":
		return "WebDAV"
	case "s3":
		return "S3"
	case "sftp":
		return "SFTP"
	}
	return kind
}

